# --- Configuration ---
app = modal.App(name="anemia-cbc-predictor")

# Add scikit-learn, tensorflow, and fastapi/pillow
image = modal.Image.debian_slim().pip_install(
    "pandas",
    "fastapi",
    "scikit-learn",
    "tensorflow",
    "Pillow",
    "python-multipart",
    "numpy"
)

# --- Base64 Encoded Model Strings ---
ENCODED_CBC_MODEL_STRING = ""
ENCODED_CBC_COLUMNS_STRING = "gASVMAAAAAAAAABdlCiMCkhlbW9nbG9iaW6UjANNQ0iUjARNQ0hDlIwDTUNWlIwIR2VuZGVyXzGUZS4="
ENCODED_VISUAL_MODEL_STRING = ""

# --- Model Class Definition ---
@app.cls(image=image)
class AnemiaPredictor:
    @modal.enter()
    def load_models(self):
        """Decode Base64 strings and load both CBC and Visual models."""
        from tensorflow.keras.models import load_model

        # --- Load Model 1 (CBC) ---
        cbc_model_path = "/tmp/anemia_model.joblib"
        columns_path = "/tmp/model_feature_columns.joblib"
        try:
            with open(cbc_model_path, "wb") as f:
                f.write(base64.b64decode(ENCODED_CBC_MODEL_STRING))
            with open(columns_path, "wb") as f:
                f.write(base64.b64decode(ENCODED_CBC_COLUMNS_STRING))
            
            self.cbc_model = joblib.load(cbc_model_path)
            self.feature_columns = joblib.load(columns_path)
            print("CBC Model loaded successfully.")
        except Exception as e:
            print(f"FATAL: Error loading CBC model: {e}")

        # --- Load Model 2 (Visual) ---
        visual_model_path = "/tmp/anemia_visual_model.h5"
        try:
            with open(visual_model_path, "wb") as f:
                f.write(base64.b64decode(ENCODED_VISUAL_MODEL_STRING))
            
            self.visual_model = load_model(visual_model_path)
            print("Visual CNN Model loaded successfully.")
        except Exception as e:
            print(f"FATAL: Error loading visual model: {e}")

    # --- Endpoint 1: CBC Prediction ---
    @modal.fastapi_endpoint(method="POST")
    def predict_cbc(self, user_input: dict):
        """API endpoint for CBC-based anemia prediction."""
        input_df = pd.DataFrame([user_input])
        processed_input_df = pd.get_dummies(input_df, columns=['Gender'])
        processed_input_df = processed_input_df.reindex(columns=self.feature_columns, fill_value=0)
        
        prediction_value = self.cbc_model.predict(processed_input_df)[0]
        probability_scores = self.cbc_model.predict_proba(processed_input_df)[0]

        return {
            "prediction_class": int(prediction_value),
            "label": "Anemic" if prediction_value == 1 else "Non-Anemic",
            "confidence_scores": {
                "non_anemic_probability": round(probability_scores[0], 4),
                "anemic_probability": round(probability_scores[1], 4)
            }
        }

    # --- Endpoint 2: Visual Prediction ---
    @modal.fastapi_endpoint(method="POST")
    async def predict_visual(self, file: UploadFile = File(...)):
        """API endpoint for visual anemia prediction using an uploaded image."""
        from tensorflow.keras.preprocessing import image as keras_image
        from tensorflow.keras.applications.mobilenet_v2 import preprocess_input

        try:
            # 1. Read uploaded image file content
            image_bytes = await file.read()
            img = keras_image.load_img(io.BytesIO(image_bytes), target_size=(224, 224))

            # 2. Process the image for MobileNetV2
            img_array = keras_image.img_to_array(img)
            img_array_expanded = np.expand_dims(img_array, axis=0)
            img_preprocessed = preprocess_input(img_array_expanded)

            # 3. Make prediction
            prediction_score = self.visual_model.predict(img_preprocessed)[0][0]
            risk_label = "High Risk" if prediction_score > 0.5 else "Low Risk"

            return {
                "risk_label": risk_label,
                "confidence_score": float(prediction_score)
            }
        except Exception as e:
            return {"error": str(e)}


